package api

import "net/http"

func (s *Server) merchantPage(w http.ResponseWriter, r *http.Request) {
	if _, ok := s.requireMerchantAccount(r); !ok || r.URL.Query().Get("view") != "panel" {
		http.Redirect(w, r, "/merchant/login", http.StatusSeeOther)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(merchantHTML))
}

func merchantLoginHTML(showError bool, signup bool) string {
	errorHTML := ""
	if showError {
		errorHTML = `<div class="error">Could not continue. Check the details and try again.</div>`
	}
	form := `
    <form method="post" action="/merchant/login">
      <label>Email<input name="email" type="email" autocomplete="email" required /></label>
      <label>Password<input name="password" type="password" autocomplete="current-password" required /></label>
      <button type="submit">Open merchant panel</button>
    </form>
    <a class="switch" href="/merchant/signup">Create a merchant account</a>`
	if signup {
		form = `
    <form method="post" action="/merchant/signup">
      <div class="row"><label>Owner name<input name="ownerName" required /></label><label>Email<input name="email" type="email" required /></label></div>
      <div class="row"><label>Password<input name="password" type="password" minlength="6" required /></label><label>Phone<input name="phone" /></label></div>
      <div class="row"><label>Shop name<input name="businessName" required /></label><label>Shop slug<input name="businessSlug" placeholder="auto if blank" /></label></div>
      <div class="row"><label>Purpose<select name="purpose"><option value="Grocery">Grocery</option><option value="Restaurant">Restaurant</option><option value="Beauty">Beauty</option><option value="Electronics">Electronics</option><option value="Home Services">Home Services</option><option value="Tailors">Tailors</option></select></label><label>Category slug<select name="categorySlug"><option value="grocery">grocery</option><option value="restaurants">restaurants</option><option value="beauty">beauty</option><option value="electronics">electronics</option><option value="home-services">home-services</option><option value="tailors">tailors</option></select></label></div>
      <label>Shop description<textarea name="shortDescription" placeholder="What should customers know first?"></textarea></label>
      <div class="row"><label>Area<input name="area" value="Kozhikode" /></label><label>WhatsApp<input name="whatsapp" /></label></div>
      <label>Address<input name="addressLabel" placeholder="Full address visible to users" /></label>
      <label>Image URL<input name="thumbnailUrl" placeholder="/mockup/im-restaurant.jpg" /></label>
      <label>Tags<input name="tags" placeholder="fresh, family, delivery" /></label>
      <button type="submit">Create shop and go live</button>
    </form>
    <a class="switch" href="/merchant/login">I already have a merchant account</a>`
	}
	title := "Merchant Login"
	lead := "Sign in to update your shop details, products, and offers."
	if signup {
		title = "Create Merchant Shop"
		lead = "Create your account and your shop will instantly appear in the Flutter app and web catalog."
	}
	return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>BNC ` + title + `</title>
  <style>
    :root{--navy:#0b2f74;--blue:#1d57ae;--ink:#06245f;--gold:#f4b227;--line:#dbe5f4;--muted:#6d7fa0;--bg:#f6f8fc;--mint:#24a870}
    *{box-sizing:border-box} body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;font-family:Inter,"Segoe UI",system-ui,sans-serif;color:var(--ink);background:linear-gradient(135deg,#061f5f,#0b2f74 48%,#2361b9)}
    .wrap{width:min(1100px,100%);display:grid;grid-template-columns:.9fr 1.1fr;gap:22px;align-items:stretch}
    .story{border-radius:30px;padding:34px;color:white;background:linear-gradient(160deg,rgba(255,255,255,.13),rgba(255,255,255,.05));border:1px solid rgba(255,255,255,.2);box-shadow:0 30px 90px rgba(2,16,52,.3)}
    .mark{width:70px;height:70px;display:grid;place-items:center;border-radius:22px;background:var(--gold);color:var(--ink);font-size:34px;font-weight:1000}
    h1{margin:24px 0 12px;font-size:44px;line-height:1.02;letter-spacing:0} p{margin:0;color:#dfebff;font-size:18px;line-height:1.55;font-weight:750}
    .metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:28px}.metric{padding:16px;border-radius:20px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.16)}.metric strong{display:block;font-size:24px}.metric span{font-size:12px;font-weight:900;color:#dce8ff}
    .card{border-radius:30px;background:white;padding:30px;box-shadow:0 30px 90px rgba(2,16,52,.24);border:1px solid rgba(255,255,255,.7)}
    .eyebrow{font-size:12px;font-weight:1000;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)} h2{margin:8px 0 8px;font-size:34px;line-height:1.05}.sub{color:var(--muted);font-size:16px;margin-bottom:22px}
    form{display:grid;gap:14px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px} label{display:grid;gap:7px;color:var(--muted);font-size:12px;font-weight:950;text-transform:uppercase}
    input,textarea,select{width:100%;border:1px solid var(--line);border-radius:16px;background:#fbfdff;color:var(--ink);padding:14px 15px;font:inherit;font-weight:800;outline:none} textarea{min-height:78px;resize:vertical} input:focus,textarea:focus,select:focus{border-color:var(--gold);box-shadow:0 0 0 4px rgba(244,178,39,.18)}
    button{border:0;border-radius:17px;padding:16px 18px;background:var(--navy);color:white;font:inherit;font-size:17px;font-weight:950;cursor:pointer}.switch{display:inline-block;margin-top:16px;color:var(--navy);font-weight:950;text-decoration:none}.error{margin:0 0 16px;padding:14px 16px;border-radius:16px;background:#fff1f1;color:#bd1c1c;font-weight:900}
    @media(max-width:850px){.wrap{grid-template-columns:1fr}.row,.metrics{grid-template-columns:1fr}h1{font-size:34px}.card,.story{padding:24px}}
  </style>
</head>
<body><main class="wrap"><section class="story"><div class="mark">B</div><h1>Merchant growth panel</h1><p>Manage one shop with focused access. Your details, catalog products, and offers publish through the shared BNC API used by the mobile app and web experience.</p><div class="metrics"><div class="metric"><strong>Live</strong><span>Catalog sync</span></div><div class="metric"><strong>1 shop</strong><span>Scoped access</span></div><div class="metric"><strong>Rich</strong><span>Storefront tools</span></div></div></section><section class="card"><div class="eyebrow">BNC Nearu</div><h2>` + title + `</h2><p class="sub">` + lead + `</p>` + errorHTML + form + `</section></main></body></html>`
}

